const body = $input.first().json.body ?? $input.first().json;
const transcript = (body.transcript_text ?? '').toString();
if (!transcript || transcript.length < 100) {
  // Degenerate fallback so the orchestrator still completes.
  return [{
    json: {
      topics: ['untitled topic'],
      novelty_score: 0,
      suggested_category: 'tech',
      image_prompt: 'editorial line art, warm cream and amber accent',
      beats: [
        { title: 'Hook' },
        { title: 'Problem' },
        { title: 'Insight' },
        { title: 'Tradeoffs' },
      ],
      pull_quote_candidates: [],
    },
  }];
}
return [{ json: { transcript_text: transcript, video_id: body.video_id } }];

// Parse Claude's JSON response. If the model returns invalid JSON, fall
// back to a safe stub so the orchestrator can still proceed.
let text = $input.first().json.message ?? $input.first().json.text ?? $input.first().json.content ?? '';
text = text.trim();
// Sometimes models wrap JSON in markdown fences despite instructions.
text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let parsed;
try {
  parsed = JSON.parse(text);
} catch (_e) {
  parsed = {
    topics: ['untitled topic'],
    novelty_score: 0,
    suggested_category: 'tech',
    image_prompt: 'editorial line art, warm cream and amber accent',
    beats: [{ title: 'Hook' }, { title: 'Problem' }, { title: 'Insight' }, { title: 'Tradeoffs' }],
    pull_quote_candidates: [],
  };
}
return [{ json: parsed }];
